<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Shared\Value\Pagination;

use Closure;
use InvalidArgumentException;

/**
 * Builds a page of items accepted by a predicate over a keyset-paginated source.
 *
 * The predicate covers rules that cannot be pushed down to the query (post-visibility), so a read
 * may return fewer accepted items than the page size. Slider keeps reading after the last row until
 * it holds one accepted item more than the page size (which tells there is a next page) or the
 * source is exhausted. It prefers few large reads over many small ones: the first read carries a
 * small lookahead, and each refill is sized from the discard ratio observed so far.
 */
final class Slider
{
    /** Safety margin over the size estimated from the observed discard ratio. */
    public const float MARGIN = 1.2;
    /** Upper bound of a single refill read (or twice the page size when larger). */
    public const int MAX_READ = 1000;

    /**
     * @template T
     * @param list<T> $values rows already read for this page
     * @param int $requested rows requested to obtain $values; fewer rows mean the source is exhausted
     * @param int $limit page size
     * @param Closure(T, int): list<T> $read reads up to the given number of rows after the given one
     * @param Closure(T): bool $accept whether a row belongs to the page
     * @return SlidePage<T>
     */
    public static function slide(array $values, int $requested, int $limit, Closure $read, Closure $accept): SlidePage
    {
        if ($limit <= 0) {
            throw new InvalidArgumentException('Page limit must be positive');
        }
        if ($requested <= 0) {
            throw new InvalidArgumentException('Requested row count must be positive');
        }
        $collected = [];
        $seen = 0;
        $batch = $values;
        while (true) {
            foreach ($batch as $item) {
                $seen++;
                if ($accept($item)) {
                    $collected[] = $item;
                    if (count($collected) > $limit) {
                        break;
                    }
                }
            }
            if (count($collected) > $limit || $batch === [] || count($batch) < $requested) {
                break;
            }
            $missing = $limit + 1 - count($collected);
            // Without any accepted item yet there is no ratio to rely on: double the last read instead.
            $requested = $collected === []
                ? max($missing, count($batch)) * 2
                : (int) ceil($missing * $seen / count($collected) * self::MARGIN);
            $requested = min($requested, max(self::MAX_READ, $limit * 2));
            $batch = $read($batch[count($batch) - 1], $requested);
        }
        return new SlidePage(array_slice($collected, 0, $limit), count($collected) > $limit);
    }
}
